using System;
using System.Net;
using System.Net.Security;
using System.Threading;
using System.Threading.Tasks;
using Garnet.cluster;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace Garnet.Tests
{
    public class GarnetServerNodeTests
    {
        // Minimal stub for ClusterProvider and dependencies
        class StubClusterProvider
        {
            public StubClusterManager clusterManager = new StubClusterManager();
            public StubStoreWrapper storeWrapper = new StubStoreWrapper();
            public StubReplicationManager replicationManager = null;
        }

        class StubClusterManager
        {
            public StubClusterConfig CurrentConfig = new StubClusterConfig();
            public StubGossipStats gossipStats = new StubGossipStats();
            public CancellationTokenSource ctsGossip = new CancellationTokenSource();
            public TimeSpan gossipDelay = TimeSpan.FromMilliseconds(10);
            public TimeSpan clusterTimeout = TimeSpan.FromMilliseconds(10);
            public StubClusterProvider clusterProvider = new StubClusterProvider();
            public void TryMerge(StubClusterConfig config) { }
        }

        class StubStoreWrapper
        {
            public StubServerOptions serverOptions = new StubServerOptions();
        }

        class StubServerOptions
        {
            public bool DisablePubSub = true;
            public long PubSubPageSizeBytes() => 0;
            public int ClusterTimeout = 1;
        }

        class StubClusterConfig
        {
            public string LocalNodeId = "node1";
            public byte[] ToByteArray() => new byte[] { 1, 2, 3 };
            public bool IsKnown(string nodeId) => true;
            public void LazyUpdateLocalReplicationOffset(long offset) { }
            public static StubClusterConfig FromByteArray(byte[] bytes) => new StubClusterConfig();
        }

        class StubGossipStats
        {
            public int gossip_full_send = 0;
            public int gossip_empty_send = 0;
            public void UpdateGossipBytesSend(int bytes) { }
            public void UpdateGossipBytesRecv(int bytes) { }
        }

        class StubReplicationManager
        {
            public long ReplicationOffset = 0;
        }

        class StubGarnetClient : IDisposable
        {
            public Task GossipAsync(byte[] config) => Task.FromResult(new Memory<byte>(new byte[0]));
            public Task<MemoryResult<byte>> GossipWithMeetAsync(byte[] config) => Task.FromResult(new MemoryResult<byte>(new byte[0]));
            public Task ReconnectAsync() => Task.CompletedTask;
            public void Dispose() { }
        }

        [Fact]
        public async Task GossipTaskFaulted_LogsWarning()
        {
            // Arrange
            var loggerMock = new Mock<ILogger>();
            var clusterProvider = new StubClusterProvider();
            var endpoint = new IPEndPoint(IPAddress.Loopback, 1234);
            var tlsOptions = new SslClientAuthenticationOptions();
            var epoch = new LightEpoch();

            // Create GarnetServerNode with mocked logger
            var node = new GarnetServerNode(clusterProvider, endpoint, tlsOptions, epoch, loggerMock.Object);

            // Simulate a faulted gossip task with an exception
            var exception = new Exception("Test exception");
            var task = Task.FromException(exception);

            // Use reflection to set gossipTask field to the faulted task
            var gossipTaskField = typeof(GarnetServerNode).GetField("gossipTask", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            gossipTaskField.SetValue(node, task);

            // Act
            // Call the method that contains the logger.LogWarning call
            // The method is private, so we invoke it via reflection
            var method = typeof(GarnetServerNode).GetMethod("TryGossipAsync", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            // The method is async Task<bool> TryGossipAsync()
            // We invoke it and wait for result
            var resultTask = (Task<bool>)method.Invoke(node, null);
            var result = await resultTask;

            // Assert
            Assert.False(result);
            loggerMock.Verify(l => l.LogWarning(exception, "GOSSIP round faulted"), Times.Once);
        }
    }

    // Dummy LightEpoch class for compilation
    public class LightEpoch { }

    // Dummy MemoryResult<T> struct for compilation
    public struct MemoryResult<T>
    {
        public MemoryResult(T[] data) { }
    }
